CREATE TABLE admin_users (id integer PRIMARY KEY CHECK(id=1), email varchar(255) NOT NULL UNIQUE, password_hash varchar(255) NOT NULL, refresh_hash varchar(255), refresh_expires timestamp with time zone, session_version bigint NOT NULL DEFAULT 0, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE child_devices (id uuid PRIMARY KEY, singleton boolean NOT NULL UNIQUE CHECK(singleton=true), name varchar(255) NOT NULL, token_hash varchar(255) NOT NULL UNIQUE, last_seen timestamp with time zone, battery integer CHECK(battery BETWEEN 0 AND 100), offline_alerted boolean NOT NULL DEFAULT false, monitoring boolean NOT NULL DEFAULT false, created_at timestamp with time zone);
CREATE TABLE device_pairings (id integer PRIMARY KEY CHECK(id=1), code_hash varchar(255), expires_at timestamp with time zone);
CREATE TABLE privacy_preferences (id integer PRIMARY KEY CHECK(id=1), value text NOT NULL);
CREATE TABLE security_audit_logs (id uuid PRIMARY KEY, occurred_at timestamp with time zone, action varchar(255) NOT NULL);
CREATE INDEX audit_time_idx ON security_audit_logs(occurred_at);
CREATE TABLE sync_queue (id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES child_devices(id) ON DELETE CASCADE, received_at timestamp with time zone);
CREATE INDEX receipt_time_idx ON sync_queue(received_at);
CREATE TABLE alerts (id uuid PRIMARY KEY, device_id uuid REFERENCES child_devices(id) ON DELETE CASCADE, occurred_at timestamp with time zone, kind varchar(255), message varchar(255), read boolean NOT NULL DEFAULT false);
CREATE INDEX alerts_time_idx ON alerts(occurred_at DESC);
CREATE TABLE permission_status (id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES child_devices(id) ON DELETE CASCADE, occurred_at timestamp with time zone NOT NULL, received_at timestamp with time zone NOT NULL, kind varchar(32) NOT NULL, package_name varchar(255), payload text NOT NULL);
CREATE INDEX permission_status_time_idx ON permission_status(device_id,occurred_at DESC);
CREATE INDEX permission_status_package_idx ON permission_status(package_name,occurred_at DESC);
CREATE TABLE installed_app_events (id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES child_devices(id) ON DELETE CASCADE, occurred_at timestamp with time zone NOT NULL, received_at timestamp with time zone NOT NULL, kind varchar(32) NOT NULL, package_name varchar(255), payload text NOT NULL);
CREATE INDEX installed_app_events_time_idx ON installed_app_events(device_id,occurred_at DESC);
CREATE INDEX installed_app_events_package_idx ON installed_app_events(package_name,occurred_at DESC);
CREATE TABLE app_usage_logs (id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES child_devices(id) ON DELETE CASCADE, occurred_at timestamp with time zone NOT NULL, received_at timestamp with time zone NOT NULL, kind varchar(32) NOT NULL, package_name varchar(255), payload text NOT NULL);
CREATE INDEX app_usage_logs_time_idx ON app_usage_logs(device_id,occurred_at DESC);
CREATE INDEX app_usage_logs_package_idx ON app_usage_logs(package_name,occurred_at DESC);
CREATE TABLE notification_events (id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES child_devices(id) ON DELETE CASCADE, occurred_at timestamp with time zone NOT NULL, received_at timestamp with time zone NOT NULL, kind varchar(32) NOT NULL, package_name varchar(255), payload text NOT NULL);
CREATE INDEX notification_events_time_idx ON notification_events(device_id,occurred_at DESC);
CREATE INDEX notification_events_package_idx ON notification_events(package_name,occurred_at DESC);
CREATE TABLE call_events (id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES child_devices(id) ON DELETE CASCADE, occurred_at timestamp with time zone NOT NULL, received_at timestamp with time zone NOT NULL, kind varchar(32) NOT NULL, package_name varchar(255), payload text NOT NULL);
CREATE INDEX call_events_time_idx ON call_events(device_id,occurred_at DESC);
CREATE INDEX call_events_package_idx ON call_events(package_name,occurred_at DESC);
CREATE TABLE location_history (id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES child_devices(id) ON DELETE CASCADE, occurred_at timestamp with time zone NOT NULL, received_at timestamp with time zone NOT NULL, kind varchar(32) NOT NULL, package_name varchar(255), payload text NOT NULL);
CREATE INDEX location_history_time_idx ON location_history(device_id,occurred_at DESC);
CREATE INDEX location_history_package_idx ON location_history(package_name,occurred_at DESC);
CREATE TABLE device_status (id uuid PRIMARY KEY, device_id uuid NOT NULL REFERENCES child_devices(id) ON DELETE CASCADE, occurred_at timestamp with time zone NOT NULL, received_at timestamp with time zone NOT NULL, kind varchar(32) NOT NULL, package_name varchar(255), payload text NOT NULL);
CREATE INDEX device_status_time_idx ON device_status(device_id,occurred_at DESC);
CREATE INDEX device_status_package_idx ON device_status(package_name,occurred_at DESC);
